cat > /etc/nginx/nginx.conf << 'EOF'
worker_processes auto;
pid /run/nginx.pid;
error_log /var/log/nginx/benchmark-error.log;
include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 768;
}

http {
    ##
    # Basic Settings
    ##

    sendfile on;
    tcp_nopush on;
    types_hash_max_size 2048;
    # server_tokens off;

    # server_names_hash_bucket_size 64;
    # server_name_in_redirect off;

    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    ##
    # SSL Settings
    ##

    ssl_protocols TLSv1 TLSv1.1 TLSv1.2 TLSv1.3; # Dropping SSLv3, ref: POODLE
    ssl_prefer_server_ciphers on;

    ##
    # Logging Settings
    ##

    # Custom log format with timestamp, method, status, and user agent
    log_format benchmark_log_format '$time_local - $request_method - $status - "$http_user_agent"';

    access_log /var/log/nginx/benchmark-access.log benchmark_log_format;

    ##
    # Rate Limiting
    ##

    # 10MB memory zone for rate limiting, 10 requests per second per IP
    limit_req_zone $binary_remote_addr zone=ratelimit:10m rate=10r/s;

    ##
    # Gzip Settings
    ##

    gzip on;

    # gzip_vary on;
    # gzip_proxied an

cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    # Rate limiting - allow burst of 10
    limit_req zone=ratelimit burst=10 nodelay;

    # Custom 404 error page
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
